--
-- Name: refresh_mv_organisation(); Type: FUNCTION; Schema: public; Owner: elisaschool_user
--

CREATE FUNCTION public.refresh_mv_organisation() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_stats_organisation;
    REFRESH MATERIALIZED VIEW CONCURRENTLY mv_postes_vacants_critiques;
END;
$$;


ALTER FUNCTION public.refresh_mv_organisation() OWNER TO elisaschool_user;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: abonnements_client; Type: TABLE; Schema: public; Owner: elisaschool_user
--

CREATE TABLE public.abonnements_client (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    "etablissementId" uuid NOT NULL,
    "planId" uuid NOT NULL,
    "dateDebut" timestamp without time zone NOT NULL,
    "dateFin" timestamp without time zone NOT NULL,
    statut public.abonnements_client_statut_enum DEFAULT 'EN_ATTENTE'::public.abonnements_client_statut_enum NOT NULL,
    "cycleFacturation" public.abonnements_client_cyclefacturation_enum DEFAULT 'MENSUEL'::public.abonnements_client_cyclefacturation_enum NOT NULL,
    "autoRenouvellement" boolean DEFAULT true NOT NULL,
    "montantMensuel" numeric(12,2) NOT NULL,
    "nombreElevesActuel" integer DEFAULT 0 NOT NULL,
    "dernierPaiement" timestamp without time zone,
    "prochaineFacturation" timestamp without time zone,
    notes text,
    "createdAt" timestamp without time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp without time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.abonnements_client OWNER TO elisaschool_user;

--
-- Name: abonnements_groupe; Type: TABLE; Schema: public; Owner: elisaschool_user
--

CREATE TABLE public.abonnements_groupe (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    "groupeEtablissementId" uuid NOT NULL,
    "planId" uuid NOT NULL,
    statut character varying(30) DEFAULT 'ACTIF'::character varying NOT NULL,
    "modeFacturation" character varying(20) DEFAULT 'consolidee'::character varying NOT NULL,
    "tarifDegressif" text,
    "repartitionFacturation" character varying(30) DEFAULT 'proportionnelle'::character varying NOT NULL,
    "dateDebut" date NOT NULL,
    "dateFin" date,
    "creePar" uuid,
    "creeAt" timestamp without time zone DEFAULT now() NOT NULL,
    "majAt" timestamp without time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.abonnements_groupe OWNER TO elisaschool_user;

--
-- Name: abonnements_modules; Type: TABLE; Schema: public; Owner: elisaschool_user
