CREATE TABLE public.abonnements_modules (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    "abonnementId" uuid NOT NULL,
    "moduleOptionnelId" uuid NOT NULL,
    actif boolean DEFAULT true NOT NULL,
    "dateActivation" timestamp without time zone,
    "dateDesactivation" timestamp without time zone,
    "createdAt" timestamp without time zone DEFAULT now() NOT NULL,
    "updatedAt" timestamp without time zone DEFAULT now() NOT NULL,
    "etablissementId" uuid NOT NULL
);


ALTER TABLE public.abonnements_modules OWNER TO elisaschool_user;

