--
-- Name: mv_postes_vacants_critiques; Type: MATERIALIZED VIEW; Schema: public; Owner: elisaschool_user
--

CREATE MATERIALIZED VIEW public.mv_postes_vacants_critiques AS
 SELECT p.id AS poste_id,
    p.intitule,
    p.code,
    (p.statut)::text AS statut,
    p."updatedAt" AS date_vacance,
    u.id AS unite_id,
    u.nom AS unite_nom,
    u.code AS unite_code,
    u."etablissementId" AS etablissement_id,
    (EXTRACT(day FROM (CURRENT_TIMESTAMP - (p."updatedAt")::timestamp with time zone)))::integer AS jours_vacance,
        CASE
            WHEN (EXTRACT(day FROM (CURRENT_TIMESTAMP - (p."updatedAt")::timestamp with time zone)) > (30)::numeric) THEN 'critique'::text
            WHEN (EXTRACT(day FROM (CURRENT_TIMESTAMP - (p."updatedAt")::timestamp with time zone)) > (15)::numeric) THEN 'avertissement'::text
            ELSE 'normal'::text
        END AS niveau_alerte
   FROM (public.postes p
     JOIN public.unites_organisationnelles u ON ((u.id = p."uniteOrganisationnelleId")))
  WHERE (((p.statut)::text = 'VACANT'::text) AND (p.actif = true) AND (u."etablissementId" IS NOT NULL))
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_postes_vacants_critiques OWNER TO elisaschool_user;

--
-- Name: mv_stats_organisation; Type: MATERIALIZED VIEW; Schema: public; Owner: elisaschool_user
--

CREATE MATERIALIZED VIEW public.mv_stats_organisation AS
 SELECT u."etablissementId" AS etablissement_id,
    count(DISTINCT u.id) AS total_unites,
    count(DISTINCT u.id) FILTER (WHERE (u.actif = true)) AS unites_actives,
    count(DISTINCT p.id) AS total_postes,
    count(DISTINCT p.id) FILTER (WHERE ((p.statut)::text = 'ACTIF'::text)) AS postes_occupes,
    count(DISTINCT p.id) FILTER (WHERE ((p.statut)::text = 'VACANT'::text)) AS postes_vacants,
    COALESCE(max(h.total_hierarchies), (0)::bigint) AS total_hierarchies,
    COALESCE(max(h.hierarchies_actives), (0)::bigint) AS hierarchies_actives,
    CURRENT_TIMESTAMP AS derniere_maj
   FROM ((public.unites_organisationnelles u
     LEFT JOIN public.postes p ON ((p."uniteOrganisationnelleId" = u.id)))
     LEFT JOIN ( SELECT hierarchie_personnel."etablissementId",
            count(*) AS total_hierarchies,
            count(*) FILTER (WHERE (hierarchie_personnel.actif = true)) AS hierarchies_actives
           FROM public.hierarchie_personnel
          GROUP BY hierarchie_personnel."etablissementId") h ON ((h."etablissementId" = u."etablissementId")))
  WHERE (u."etablissementId" IS NOT NULL)
  GROUP BY u."etablissementId"
  WITH NO DATA;


ALTER MATERIALIZED VIEW public.mv_stats_organisation OWNER TO elisaschool_user;

